mapper.select:
SELECT t.*
FROM tab_wf_approval_task t
INNER JOIN tab_wf_process_instance p ON p.id = t.process_instance_id
WHERE t.id IN
#{taskId}
AND p.business_type = #{businessType}
ORDER BY t.create_time DESC, t.id DESC
LIMIT #{offset}, #{limit}

SELECT t.*
FROM tab_wf_approval_task t
INNER JOIN (
    SELECT r.task_id, MAX(r.id) AS max_id
    FROM tab_wf_approval_record r
    WHERE r.operator_id = #{operatorId}
    AND r.task_id IS NOT NULL
    AND r.action IN
    #{action}
    GROUP BY r.task_id
) latest ON t.id = latest.task_id
INNER JOIN tab_wf_approval_record rec ON rec.id = latest.max_id
INNER JOIN tab_wf_process_instance p ON p.id = t.process_instance_id

    AND p.business_type = #{businessType}

ORDER BY rec.create_time DESC, rec.id DESC
LIMIT #{offset}, #{limit}
